def test_aggregate_by_key_partitioning(self):
    ht1 = hl.Table.parallelize([{'k': 'foo', 'b': 1}, {'k': 'bar', 'b': 2}, {'k': 'bar', 'b': 2}], hl.tstruct(k=hl.tstr, b=hl.tint32), key='k')
